static inline void gpio_set_mode(gpio* port, uint8_t pin, gpio_modes mode) {
    uint32_t shift = 2U * pin;  // Each pin is 2 bits wide
    uint32_t reg = port->MODER;

    reg &= ~(3U << shift);              // Clear bit
    reg |= ((uint32_t)mode << shift);     // Set bit

    port->MODER = reg;
}

